       padding: 2rem;
       background:
         radial-gradient(circle at top left, rgba(139, 92, 246, 0.22), transparent 30rem),
         linear-gradient(135deg, #020617 0%, var(--bg) 100%);
       color: var(--text);
       font-family: Arial, Helvetica, sans-serif;
       line-height: 1.5;
     }

     main {
       width: min(100%, 32rem);
