       align-items: center;
       gap: 0.75rem;
       margin-top: 0.75rem;
       padding: 0.9rem 1rem;
       border: 1px solid var(--border);
       border-radius: 0.85rem;
       background: var(--panel-light);
       cursor: pointer;
       transition: border-color 160ms ease, transform 160ms ease, background 160ms ease;
     }

