   <main>
     <form id="notification-form">
       <h1>Notification Preferences</h1>
       <p class="intro">Choose the one option that works best for you.</p>

       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>

           <label class="radio-option" for="notification-email">
             <input type="radio" id="notification-email" name="notificationPreference" value="Email" required>
             <span>Email</span>
           </label>

           <label class="radio-option" for="notification-sms">
             <input type="radio" id="notification-sms" name="notificationPreference" value="SMS">
             <span>SMS</span>
           </label>

           <label class="radio-option" for="notification-push">
             <input type="radio" id="notification-push" name="notificationPreference" value="Push Notifications">
             <span>Push Notifications</span>
           </label>
